import { useState } from "react";

function Contador() {
  const [contagem, setContagem] = useState(0);

  return (
    <div>
      <p>Voce clicou {contagem} vezes</p>
      <button onClick={() => setContagem(contagem + 1)}>
        Clicar
      </button>
    </div>
  );
}

// ERRADO -- nao faz nada na tela
contagem = contagem + 1;

// CERTO -- avisa o React que precisa redesenhar
setContagem(contagem + 1);

// Funciona, mas pode causar bugs se chamado varias vezes seguidas
setContagem(contagem + 1);

// Mais seguro: recebe o valor mais atualizado garantido
setContagem((valorAtual) => valorAtual + 1);

import { useState } from "react";

function CampoNome() {
  const [nome, setNome] = useState("");

  return (
    <input
      type="text"
      value={nome}
      onChange={(e) => setNome(e.target.value)}
      placeholder="Seu nome"
    />
  );
}

function FormularioContato() {
  const [dados, setDados] = useState({
    nome: "",
    email: "",
    mensagem: "",
  });

  function atualizarCampo(campo, valor) {
    setDados({ ...dados, [campo]: valor });
  }

  return (
    <form>
      <input
        value={dados.nome}
        onChange={(e) => atualizarCampo("nome", e.target.value)}
      />
      <input
        value={dados.email}
        onChange={(e) => atualizarCampo("email", e.target.value)}
      />
    </form>
  );
}

import { useState, useEffect } from "react";

function Contador() {
  const [contagem, setContagem] = useState(0);

  useEffect(() => {
    document.title = `Cliques: ${contagem}`;
  }, [contagem]);

  return (
    <button onClick={() => setContagem(contagem + 1)}>
      Cliquei {contagem} vezes
    </button>
  );
}
